func NewScanner(s io.Reader) *Scanner {
	return &Scanner{br: bufio.NewReader(s)}
}

func (sc *Scanner) next() string {
	for sc.st == nil || sc.pos >= len(sc.st) {
		line, _ := sc.br.ReadString('\n')
		sc.st = strings.Fields(line)
		sc.pos = 0
	}
	token := sc.st[sc.pos]
	sc.pos++
	return token
}

func (sc *Scanner) nextInt() int {
	v, _ := strconv.Atoi(sc.next())
	return v
}

func (sc *Scanner) nextLong() int64 {
	v, _ := strconv.ParseInt(sc.next(), 10, 64)
	return v
}

func (sc *Scanner) nextLine() string {
	line, _ := sc.br.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
